  ('0c62c754-4b7d-5d67-8168-1b98f3bf92df', '55555555-5555-5555-5555-555555555556', 'Verduras y hortalizas (frecuencia de consumo)', 'opcion', 'd1_1_i', 'espinaca, acelga, brócoli, tomate, zanahoria, ahuyama, remolacha, pepino (frescas, de hoja verde y fuente de vitamina A) · Un puño cerrado', 'Alimentación', 1, 'clinical', false),
  ('1e54221a-aa62-54c4-8d83-d7abe266c426', '55555555-5555-5555-5555-555555555556', 'Frutas enteras (frecuencia de consumo)', 'opcion', 'd1_2_i', 'banano, mango, papaya, guayaba, naranja, lulo, tomate de árbol (enteras, no en jugo) · 1 fruta mediana o un pocillo', 'Alimentación', 2, 'clinical', false),
  ('0a5e5582-f2b5-573e-8769-d8166bb734f3', '55555555-5555-5555-5555-555555555556', 'Leguminosas (frecuencia de consumo)', 'opcion', 'd1_3_i', 'fríjol, lenteja, garbanzo, arveja, habas · Un pocillo arriero cocido', 'Alimentación', 3, 'clinical', false),
  ('23aed6bf-c7dc-5194-8783-5f43be6a7585', '55555555-5555-5555-5555-555555555556', 'Pescado y mariscos (frecuencia de consumo)', 'opcion', 'd1_4_i', 'atún, sardina, bocachico, tilapia, salmón, camarón (frescos, refrigerados o congelados) · Tamaño de su celular', 'Alimentación', 4, 'clinical', false),
  ('904477df-44c1-5f4d-8367-64ee0794defc', '55555555-5555-5555-5555-555555555556', 'Grasas saludables (frecuencia de consumo)', 'opcion', 'd1_5_i', 'aguacate, aceite de oliva (preferiblemente extra virgen), maní, nueces, almendras, semillas, coco · ¼ aguacate, 1 cucharadita de aceite o un puñado de frutos secos', 'Alimentación', 5, 'clinical', false),
  ('fe4df98c-4b9c-5ada-8a89-1d0373c7dbb5', '55555555-5555-5555-5555-555555555556', 'Lácteos y fermentados (frecuencia de consumo)', 'opcion', 'd1_6_i', 'leche, yogur natural, kumis, kéfir, queso fresco · 1 vaso o 2 cucharadas de queso', 'Alimentación', 6, 'clinical', false),
  ('0bb094ef-fe2e-514e-8f4b-98cf9d9e4b0e', '55555555-5555-5555-5555-555555555556', 'Huevos (frecuencia de consumo)', 'opcion', 'd1_7_i', 'huevo entero · 1 unidad', 'Alimentación', 7, 'clinical', false),
  ('cfdac03e-9e60-5c50-8368-6173524c9fe4', '55555555-5555-5555-5555-555555555556', 'Cereales integrales y otros (frecuencia de consumo)', 'opcion', 'd1_8_i', 'avena, quinua, maíz, arroz integral, cebada, cuchuco, pan integral · ½ pocillo cocido o 1 tajada', 'Alimentación', 8, 'clinical', false),
  ('ffebdf3c-20f4-5d87-8bd7-421d01622a68', '55555555-5555-5555-5555-555555555556', 'Raíces, tubérculos y plátanos (frecuencia de consumo)', 'opcion', 'd1_9_i', 'papa, yuca, plátano, arracacha, ñame, batata · 1 papa mediana o ½ plátano', 'Alimentación', 9, 'clinical', false),
  ('73dc09b2-6a33-5191-81ac-a366f8648d96', '55555555-5555-5555-5555-555555555556', 'Carnes blancas (frecuencia de consumo)', 'opcion', 'd1_10_i', 'pollo, pavo, aves sin piel · Tamaño de su celular (~90 g)', 'Alimentación', 10, 'clinical', false),
  ('cc94bde5-6791-52f6-840a-bc4a8e89ff78', '55555555-5555-5555-5555-555555555556', 'Carnes rojas (frecuencia de consumo)', 'opcion', 'd1_15_i', 'res, cerdo magro, cordero (frescas); vísceras 1 vez por semana (hierro) · Tamaño de su celular (~90 g)', 'Alimentación', 11, 'clinical', false),
  ('1d2728f4-ec2d-5613-8046-6e6990cb08c1', '55555555-5555-5555-5555-555555555556', 'Cereales refinados y harinas blancas (frecuencia de consumo)', 'opcion', 'd1_11_i', 'pan blanco, arroz blanco, pasta blanca, galletas, arepa de harina refinada · ½ pocillo o 1 unidad', 'Alimentación', 12, 'clinical', false),
